import React from "react";
import { DatePicker, FormItem } from "@storage-fe/formily-arco";
import { createForm } from "@formily/core";
import { FormProvider, Field } from "@formily/react";

const form = createForm();

export default () => (
  <FormProvider form={form}>
    <Field
      name="datePicker"
      title="日期选择器"
      decorator={[FormItem]}
      component={[DatePicker]}
      initialValue="2022-25-25"
    />
    <Field
      name="MonthPicker"
      title="月份选择器"
      decorator={[FormItem]}
      component={[DatePicker.MonthPicker]}
      initialValue="2022-10"
    />
    <Field
      name="WeekPicker"
      title="周选择器"
      decorator={[FormItem]}
      component={[DatePicker.WeekPicker]}
      initialValue="2022-1周"
    />
    <Field
      name="QuarterPicker"
      title="季度选择器"
      decorator={[FormItem]}
      component={[DatePicker.QuarterPicker]}
      initialValue={"2023-Q4"}
    />

    <Field
      name="timePicker"
      title="带时间的选择器"
      decorator={[FormItem]}
      component={[DatePicker, { showTime: true }]}
      initialValue="2022-25-25"
    />

    <Field
      name="rangePickerDate"
      title="天范围选择器"
      decorator={[FormItem]}
      component={[DatePicker.RangePicker, { mode: "date" }]}
    />
    <Field
      name="rangePickerWeek"
      title="周范围选择器"
      decorator={[FormItem]}
      component={[DatePicker.RangePicker, { mode: "week" }]}
      initialValue={["2022-1周", "2022-2周"]}
    />
    <Field
      name="rangePickerWeekFormat"
      title="周范围选择器-有自定义格式"
      decorator={[FormItem]}
      component={[DatePicker.RangePicker, { mode: "week", format: "wo-gggg" }]}
      initialValue={["1周-2022", "2周-2022"]}
    />
    <Field
      name="rangePickerQuarter"
      title="季度范围选择器"
      decorator={[FormItem]}
      component={[DatePicker.RangePicker, { mode: "quarter" }]}
      initialValue={["2023-Q4", "2024-Q1"]}
    />
    <Field
      name="rangePickerMonth"
      title="月范围选择器"
      decorator={[FormItem]}
      component={[DatePicker.RangePicker, { mode: "month" }]}
    />
    <Field
      name="rangePickerYear"
      title="年范围选择器"
      decorator={[FormItem]}
      component={[DatePicker.RangePicker, { mode: "year" }]}
    />
  </FormProvider>
);
